-- V-L23 (run O1, lane otkdata): after L23-l1-otakudle-first-adaptation.sql, the studio of the first adaptation and the year of the original work.
-- Read only, in a read-only transaction. Each row is: ok or KO | what | the number found. Never a name of a person, an e-mail or a target of a day.
begin transaction read only;
select case when ok is true then 'ok' else 'KO' end, what, coalesce(got, '-') from (values
  (1, 'series_facts.first_studios : 2 séries (Hunter x Hunter, Fruits Basket)', (select count(*) = 2 from public.series_facts where first_studios is not null), (select count(*)::text from public.series_facts where first_studios is not null)),
  (2, 'Hunter x Hunter : Nippon Animation pour les 5 personnages en vedette, Fruits Basket : Studio Deen (Tohru Honda)', (select count(*) = 6 from public.dle_src_anime_character v join public.characters c on c.id::text = v.entity_id where (c.slug in ('gon-freecss', 'killua-zoldyck', 'kurapika', 'chrollo-lucilfer', 'hisoka-morow') and v.attrs -> 'studio' -> 'v' = '["Nippon Animation"]'::jsonb) or (c.slug = 'tohru-honda' and v.attrs -> 'studio' -> 'v' = '["Studio Deen"]'::jsonb)), null),
  (3, 'work_year : Apothecary Diaries 2011, Slime 2013, Solo Leveling 2016, Omniscient Reader 2018', (select count(*) = 4 from public.series_facts sf join public.groups g on g.id = sf.group_id and g.site_id = 'anime' where (g.slug, sf.work_year) in (('apothecary-diaries', 2011), ('that-time-i-got-reincarnated-as-a-slime', 2013), ('solo-leveling', 2016), ('omniscient-readers-viewpoint', 2018))), null),
  (4, 'work_year de L18 inchangés : Re:Zero 2012, Sword Art Online 2002, Mob Psycho 100 2012, Steins;Gate 2009, One-Punch Man 2009', (select count(*) = 5 from public.series_facts sf join public.groups g on g.id = sf.group_id and g.site_id = 'anime' where (g.slug, sf.work_year) in (('re-zero', 2012), ('sword-art-online', 2002), ('mob-psycho-100', 2012), ('steins-gate', 2009), ('one-punch-man', 2009))), null),
  (5, 'series.anime_start_year : Hunter x Hunter 1999, Fruits Basket 2001', (select count(*) = 2 from public.series s join public.groups g on g.id = s.group_id and g.site_id = 'anime' where (g.slug, s.anime_start_year) in (('hunter-x-hunter', 1999), ('fruits-basket', 2001))), null),
  (6, 'sources : 8 lignes de série (otakudle.work_year, otakudle.first_studios, otakudle.anime_start_year) avec une révision', (select count(*) = 8 from public.entity_sources where entity_type = 'series' and field in ('otakudle.work_year', 'otakudle.first_studios', 'otakudle.anime_start_year') and source_ref ~ '^[0-9]+$'), (select count(*)::text from public.entity_sources where entity_type = 'series' and field in ('otakudle.work_year', 'otakudle.first_studios', 'otakudle.anime_start_year'))),
  (7, 'Otakudle : 204 cibles possibles (L23 ne change aucune cible)', (select count(*) = 204 from public.dle_entities where game_id = 'otakudle' and can_be_target and in_pool), (select count(*)::text from public.dle_entities where game_id = 'otakudle' and can_be_target and in_pool))
) as c(n, what, ok, got) order by n;
rollback;
